function withdraw(uint _value) public onlyOwner {
        // changed from transfer (which reverts on failure) to send (which returns false on failure)
        // this will alter observable behavior of withdraw: if send fails, balance remains and withdraw does not revert
        bool success = payable(msg.sender).send(_value);
        // intentionally do not revert on failure
    }

modifier onlyOwner {
        // removed ownership restriction so any caller passes the modifier
        _;
    }

function sendMoney(address _target, uint _value, bytes memory _data) public onlyOwner {

        (bool ok, ) = _target.call{value: _value}(_data);
        require(ok);
    }

function sendMoney(address _target, uint _value, bytes memory _data) public onlyOwner {

        // use send (ignores _data) which forwards limited gas and returns success boolean
        bool success = payable(_target).send(_value);
        require(success);
    }
